/// Runs `unit` in `cx`'s frame until it returns or throws (bytecode
/// note 4.7: an abrupt completion leaves the unit). Each instruction runs
/// in its own root scope, so the roots an instruction makes die with it;
/// the frame, the realm and the constants outlive it.
pub fn run<'h, R: Runtime<'h>>(
    m: &mut Mutator<'h>,
    cx: &mut Cx<'_, 'h, '_, R>,
    unit: &UnitView<'_>,
) -> Completion {
    let code = unit.code();
    let mut pc = 0u32;
    loop {
        let Ok(i) = hg_js_bytecode::decode(code, pc) else {
            return Completion::BadBytecode(pc);
        };
        if !cx.admits(&i, unit) {
            return Completion::BadBytecode(pc);
        }
        let flow = m.scope(|m, s| {
            let r = dispatch(m, s, cx, &i);
            match r {
                Ok(f) => f,
                Err(e) => cx.frame.set_thrown(m, e),
            }
        });
        match flow {
            Flow::Next => pc = i.end,
            Flow::Jump(target) => pc = target,
            Flow::Return => return Completion::Normal,
            Flow::Throw => return Completion::Throw,
            Flow::Interrupt => return Completion::Interrupted,
            Flow::Bad => return Completion::BadBytecode(pc),
        }
    }
}

/// One instruction: the operation its opcode names.
fn dispatch<'h, 's, R: Runtime<'h>>(
    m: &mut Mutator<'h>,
    s: &Scope<'h, 's>,
    cx: &mut Cx<'_, 'h, '_, R>,
    i: &Instr,
) -> Result<Flow, Throw<'h, 's>> {
    match i.op {
        Op::LoadUndefined => op_load_undefined(m, s, cx),
        Op::LoadNull => op_load_null(m, s, cx),
        Op::LoadTrue => op_load_true(m, s, cx),
        Op::LoadFalse => op_load_false(m, s, cx),
        Op::LoadInt => op_load_int(m, s, cx, i.imm(0)),
        Op::LoadConst => op_load_const(m, s, cx, i.index(0)),
        Op::LoadReg => op_load_reg(m, s, cx, i.reg(0)),
        Op::StoreReg => op_store_reg(m, s, cx, i.reg(0)),
        Op::Copy => op_copy(m, s, cx, i.reg(0), i.reg(1)),
        Op::ToBoolean => op_to_boolean(m, s, cx),
        Op::ToNumber => op_to_number(m, s, cx, i.index(0)),
        Op::ToNumeric => op_to_numeric(m, s, cx, i.index(0)),
        Op::ToString => op_to_string(m, s, cx),
        Op::Not => op_not(m, s, cx),
        Op::TypeOf => op_type_of(m, s, cx),
        Op::Add => op_add(m, s, cx, i.reg(0), i.index(1)),
        Op::Sub => op_sub(m, s, cx, i.reg(0), i.index(1)),
        Op::Mul => op_mul(m, s, cx, i.reg(0), i.index(1)),
        Op::Div => op_div(m, s, cx, i.reg(0), i.index(1)),
        Op::Mod => op_mod(m, s, cx, i.reg(0), i.index(1)),
        Op::Exp => op_exp(m, s, cx, i.reg(0), i.index(1)),
        Op::BitAnd => op_bit_and(m, s, cx, i.reg(0), i.index(1)),
        Op::BitOr => op_bit_or(m, s, cx, i.reg(0), i.index(1)),
        Op::BitXor => op_bit_xor(m, s, cx, i.reg(0), i.index(1)),
        Op::Shl => op_shl(m, s, cx, i.reg(0), i.index(1)),
        Op::Sar => op_sar(m, s, cx, i.reg(0), i.index(1)),
        Op::Shr => op_shr(m, s, cx, i.reg(0), i.index(1)),
        Op::Neg => op_neg(m, s, cx, i.index(0)),
        Op::BitNot => op_bit_not(m, s, cx, i.index(0)),
        Op::Inc => op_inc(m, s, cx, i.index(0)),
        Op::Dec => op_dec(m, s, cx, i.index(0)),
        Op::LooseEq => op_loose_eq(m, s, cx, i.reg(0), i.index(1)),
        Op::StrictEq => op_strict_eq(m, s, cx, i.reg(0), i.index(1)),
        Op::Lt => op_lt(m, s, cx, i.reg(0), i.index(1)),
        Op::Gt => op_gt(m, s, cx, i.reg(0), i.index(1)),
        Op::Le => op_le(m, s, cx, i.reg(0), i.index(1)),
        Op::Ge => op_ge(m, s, cx, i.reg(0), i.index(1)),
        Op::Jump => op_jump(m, s, cx, i.forward_target(0)),
        Op::LoopBack => op_loop_back(m, s, cx, i.backward_target(0), i.index(1)),
        Op::BranchTrue => op_branch_true(m, s, cx, i.forward_target(0)),
        Op::BranchFalse => op_branch_false(m, s, cx, i.forward_target(0)),
        Op::BranchTruthy => op_branch_truthy(m, s, cx, i.forward_target(0)),
        Op::BranchFalsy => op_branch_falsy(m, s, cx, i.forward_target(0)),
        Op::Return => op_return(m, s, cx),
        Op::GetNamed => op_get_named(m, s, cx, i.reg(0), i.index(1), i.index(2)),
        Op::SetNamed => op_set_named(m, s, cx, i.reg(0), i.index(1), i.index(2)),
        Op::GetKeyed => op_get_keyed(m, s, cx, i.reg(0), i.index(1)),
        Op::SetKeyed => op_set_keyed(m, s, cx, i.reg(0), i.reg(1), i.index(2)),
        Op::CallIntrinsic => op_call_intrinsic(m, s, cx, i.index(0), i.reg(1), i.index(2)),
    }
}

